      const importBook=async(name,document)=>view(`edit(document.querySelector('input[aria-label="新世界书名称"]'),${JSON.stringify(name)});await choose(${JSON.stringify(encode(document))},${JSON.stringify(name+'.json')},'application/json',document.querySelector('input[aria-label="导入世界书 JSON"]'));await wait(()=>document.querySelector('.world-info-dock h3')?.textContent===${JSON.stringify(name)},'candidate imported world');`);
